            setLoginRole('patient');
            setAbhaInput('91-4523-8819-2041');
            setOtpSent(false);
          }}
          className={`flex-1 py-2 text-xs font-bold rounded-lg transition-colors flex items-center justify-center gap-1.5 ${
            loginRole === 'patient'
              ? 'bg-white text-teal-900 shadow-xs'
