        >
          <Stethoscope className="w-3.5 h-3.5 text-teal-600" />
          <span>Doctor (HPR)</span>
        </button>
      </div>

      {/* Login Form */}
      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-5">
